const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-96.111167, 29.956182]);
  const region = point.buffer(4000); // 4km radius
  const dates = {
    d1: {date: '2013-05-04', window: '2013-05-01', name: '2013'},
    d2: {date: '2016-05-28', window: '2016-05-25', name: '2016'}
  };

  // Function to get water extent using Sentinel-1 SAR (VV band threshold)
  async function getWaterExtent(targetDate, windowStart) {
    const col = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(region)
      .filterDate(windowStart, ee.Date(targetDate).advance(3, 'day'))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
      .select('VV');

    const size = col.size().getInfo();
    if (size === 0) {
      return {count: null, total: null, img: null};
    }

    const img = col.mean().clip(region);
    // Water detection: VV < -16 dB threshold (adjustable for your region)
    const water = img.lt(-16);

    const stats = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 100,
      maxPixels: 1e9
    });

    const count = stats.get('VV').getInfo();
    const totalPixels = water.unmask(0).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 100,
      maxPixels: 1e9
    }).get('VV').getInfo();

    return {count, total: totalPixels, img: water};
  }

  // 2. Data Acquisition & Processing
  console.log('Fetching Sentinel-1 SAR data...');
  const results = {};

  for (const [key, spec] of Object.entries(dates)) {
    const result = await getWaterExtent(spec.date, spec.window);
    results[spec.name] = result;
    console.log(`${spec.name}: Images available - ${result.img ? 'Yes' : 'No'}, ` +
                `Water pixels - ${result.count !== null ? result.count : 'N/A'}`);
  }

  // 3. Validation
  if (results['2013'].count === null || results['2016'].count === null) {
    console.log('<answer>C1</answer>');
    return;
  }

  if (results['2013'].total === 0 || results['2016'].total === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (results['2013'].count === undefined || results['2016'].count === undefined ||
      isNaN(results['2013'].count) || isNaN(results['2016'].count)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 4. Comparison
  const change = results['2016'].count - results['2013'].count;
  const percentChange = (change / results['2013'].count) * 100;

  console.log(`2013 water pixels: ${results['2013'].count.toLocaleString()}`);
  console.log(`2016 water pixels: ${results['2016'].count.toLocaleString()}`);
  console.log(`Change: ${change.toLocaleString()} pixels (${percentChange.toFixed(1)}%)`);

  // 5. Final Answer
  console.log(change > 0 ? '<answer>A</answer>' : '<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
